<?php
declare(strict_types=1);
namespace Zandu\Modules\Inventory\Presentation\Api;
use ApiPlatform\Metadata\Operation;use ApiPlatform\State\ProviderInterface;use InvalidArgumentException;use Zandu\Modules\Inventory\Application\StockMovementQueryService;use Zandu\SharedKernel\Context\CurrentActorProvider;use Zandu\SharedKernel\Identity\{ProductId,StoreId,UuidFactory};use Zandu\SharedKernel\Tenancy\TenantTransaction;
/** @implements ProviderInterface<StockMovementResource> */
final readonly class StockMovementProvider implements ProviderInterface{public function __construct(private CurrentActorProvider $actors,private UuidFactory $uuids,private TenantTransaction $transaction,private StockMovementQueryService $queries){}public function provide(Operation $operation,array $uriVariables=[],array $context=[]):array{$actor=$this->actors->resolve();$store=$this->parse($uriVariables['storeId']??null,StoreId::class);$product=null!==($uriVariables['productId']??null)?$this->parse($uriVariables['productId'],ProductId::class):null;return $this->transaction->transactional($actor->organizationId(),fn():array=>array_map(fn(array $v):StockMovementResource=>new StockMovementResource(...array_values($v)),$this->queries->list($actor,$store,$product)));}private function parse(mixed $v,string $type):StoreId|ProductId{if(!is_string($v)||''===$v)throw new InvalidArgumentException('Identifier is required.');return $type===StoreId::class?StoreId::fromString($v,$this->uuids):ProductId::fromString($v,$this->uuids);}}
